# Vials-to-rack scene plus one transparent PET bottle prop.
#
# Everything is inherited from vials_to_rack_env_cfg unchanged; this file only
# adds the bottle (and a reset term so it goes back to its start pose), and turns
# on RTX translucency so the glass material renders. The existing tasks are untouched.
#
# The bottle asset is generated by asset_gen/make_bottle.py into
# source/sim_to_real_so101/assets/usd/Bottle.usda.
#
# Optional fill, chosen with environment variables when launching (default: empty bottle):
#   BOTTLE_FILL=none|beads|pbd     what goes inside
#   BOTTLE_FILL_FRACTION=0.4       liquid level as a fraction of the inside height (floor to rim)
#   BOTTLE_BEAD_RADIUS_MM=2.5      beads: sphere radius
#   BOTTLE_MAX_BEADS=600           beads: cap on the number of rigid bodies
#   BOTTLE_PBD_SPACING_MM=2.5      pbd: particle spacing (smaller = more particles, slower)
#   BOTTLE_PBD_ISOSURFACE=0|1      pbd: render a liquid surface instead of particle spheres
# Both fills need the hollow collider (make_bottle.py --collider hollow, the default).
import os

import isaaclab.sim as sim_utils
from isaaclab.assets import RigidObjectCfg
from isaaclab.envs import mdp as isaaclab_mdp
from isaaclab.managers import EventTermCfg as EventTerm
from isaaclab.managers import SceneEntityCfg
from isaaclab.utils import configclass

from sim_to_real_so101 import assets
from sim_to_real_so101.utils.bottle_fill import (
    make_bead_collection_cfg,
    reset_beads,
    reset_pbd_liquid,
    spawn_pbd_liquid,
)

from .vials_to_rack_env_cfg import (
    VialsToRackDREnvCfg,
    VialsToRackDRSceneCfg,
    VialsToRackEnvCfg,
    VialsToRackEventCfg,
    VialsToRackEventDRCfg,
    VialsToRackSceneCfg,
)

assets_path = os.path.dirname(os.path.abspath(assets.__file__))

# Origin of Bottle.usda is the centre of its base. The mat surface sits at z ~0.032,
# so spawning the base at 0.045 drops it ~1 cm onto the mat. Mass, COM, inertia,
# collider and friction all come from the USD itself.
BOTTLE_USD = f"{assets_path}/usd/Bottle.usda"
BOTTLE_POS = (0.12, -0.12, 0.045)
BOTTLE_CFG = RigidObjectCfg(
    prim_path="{ENV_REGEX_NS}/Bottle",
    spawn=sim_utils.UsdFileCfg(
        usd_path=BOTTLE_USD,
        rigid_props=sim_utils.RigidBodyPropertiesCfg(angular_damping=5.0),
    ),
    init_state=RigidObjectCfg.InitialStateCfg(pos=BOTTLE_POS),
)

# Put the bottle back to its start pose on every reset (pose/velocity ranges empty = no randomization).
RESET_BOTTLE = EventTerm(
    func=isaaclab_mdp.reset_root_state_uniform,
    mode="reset",
    params={"pose_range": {}, "velocity_range": {}, "asset_cfg": SceneEntityCfg("bottle")},
)


def apply_bottle_fill(env_cfg) -> None:
    """Add beads or PBD liquid inside the bottle according to the BOTTLE_* environment variables."""
    fill = os.getenv("BOTTLE_FILL", "none").strip().lower()
    if fill in ("", "none", "0"):
        return
    fraction = float(os.getenv("BOTTLE_FILL_FRACTION", "0.4"))
    if fill == "beads":
        env_cfg.scene.beads = make_bead_collection_cfg(
            BOTTLE_USD,
            BOTTLE_POS,
            fill=fraction,
            bead_radius=float(os.getenv("BOTTLE_BEAD_RADIUS_MM", "2.5")) * 1e-3,
            max_beads=int(os.getenv("BOTTLE_MAX_BEADS", "600")),
        )
        env_cfg.events.reset_beads = EventTerm(
            func=reset_beads, mode="reset", params={"asset_cfg": SceneEntityCfg("beads")}
        )
    elif fill == "pbd":
        # prestartup events edit the USD stage before the sim starts, which Isaac Lab only
        # allows without physics replication (fine here: teleop always runs one env)
        env_cfg.scene.replicate_physics = False
        env_cfg.events.spawn_liquid = EventTerm(
            func=spawn_pbd_liquid,
            mode="prestartup",
            params={
                "usd_path": BOTTLE_USD,
                "bottle_pos": BOTTLE_POS,
                "fill": fraction,
                "spacing": float(os.getenv("BOTTLE_PBD_SPACING_MM", "2.5")) * 1e-3,
                "isosurface": os.getenv("BOTTLE_PBD_ISOSURFACE", "0") == "1",
            },
        )
        env_cfg.events.reset_liquid = EventTerm(func=reset_pbd_liquid, mode="reset")
    else:
        raise ValueError(f"BOTTLE_FILL must be none, beads or pbd, got {fill!r}")


@configclass
class VialsBottleSceneCfg(VialsToRackSceneCfg):
    bottle = BOTTLE_CFG.replace()


@configclass
class VialsBottleDRSceneCfg(VialsToRackDRSceneCfg):
    bottle = BOTTLE_CFG.replace()


@configclass
class VialsBottleEventCfg(VialsToRackEventCfg):
    reset_bottle = RESET_BOTTLE


@configclass
class VialsBottleEventDRCfg(VialsToRackEventDRCfg):
    reset_bottle = RESET_BOTTLE


@configclass
class VialsBottleEnvCfg(VialsToRackEnvCfg):
    scene: VialsBottleSceneCfg = VialsBottleSceneCfg()
    events: VialsBottleEventCfg = VialsBottleEventCfg()

    def __post_init__(self) -> None:
        super().__post_init__()
        self.sim.render.enable_translucency = True  # base cfg turns it off; glass needs it
        apply_bottle_fill(self)


@configclass
class VialsBottleDREnvCfg(VialsToRackDREnvCfg):
    scene: VialsBottleDRSceneCfg = VialsBottleDRSceneCfg()
    events: VialsBottleEventDRCfg = VialsBottleEventDRCfg()

    def __post_init__(self) -> None:
        super().__post_init__()
        self.sim.render.enable_translucency = True
        apply_bottle_fill(self)
